      <div style={{ blockSize: 600, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Popover
          size="medium"
          header="Lorem ipsum"
          content={<div>{loading ? content.slice(0, 200) + '...' : content}</div>}
          dismissAriaLabel="Close"
          renderWithPortal={urlParams.renderWithPortal}
        >
          Click!
        </Popover>
      </div>
    </>
  );
}

